  font-family: 'Playfair Display', serif;
}
.bottle-label .lname { font-size: 18px; font-weight: 700; }
.bottle-label .lsub { font-size: 9px; letter-spacing: .3em; color: var(--muted); margin-top: 6px; text-transform: uppercase; }

.hero-badge {
  position: absolute; top: 32px; right: 32px;
  width: 110px; height: 110px; border-radius: 50%;
  background: var(--ink); color: #fff;
  display: flex; align-items: center; justify-content: center;
  text-align: center; font-size: 11px; line-height: 1.3; font-weight: 600;
  letter-spacing: .1em; text-transform: uppercase;
  animation: spin 18s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
.hero-stats {
  position: absolute; left: 56px; bottom: 40px;
  display: flex; gap: 40px;
}
.hero-stat .num {
  font-family: 'Playfair Display', serif; font-size: 26px; font-weight: 600;
}
.hero-stat .lbl {
  font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .15em; margin-top: 2px;
}

/* ---------- Marquee ---------- */
.marquee {
  margin-top: 56px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
  background: var(--bg);
}
.marquee-track {
  display: flex; gap: 60px;
  padding: 22px 0;
  animation: marquee 35s linear infinite;
  white-space: nowrap;
}
.marquee-item {
  font-family: 'Playfair Display', serif;
  font-size: 22px; font-weight: 500;
  display: inline-flex; align-items: center; gap: 60px;
  color: var(--muted);
}
.marquee-item span { color: var(--brand); }
@keyframes marquee {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

/* ---------- Section ---------- */
section { padding: 88px 0; }
.section-head {
  display: flex; justify-content: space-between; align-items: end;
  margin-bottom: 40px; gap: 24px; flex-wrap: wrap;
}
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.8rem, 3.5vw, 2.6rem);
  margin: 8px 0 0; font-weight: 600; letter-spacing: -0.01em;
}
.section-sub { color: var(--muted); max-width: 480px; margin-top: 12px; }
.see-all {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 14px; font-weight: 600;
  border-bottom: 1px solid var(--ink); padding-bottom: 4px;
}
.see-all:hover { color: var(--brand); border-color: var(--brand); }

/* ---------- Categories ---------- */
.cats {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 18px;
}
.cat {
  position: relative; aspect-ratio: 4/5;
  border-radius: var(--radius); overflow: hidden;
  background: var(--surface);
  cursor: pointer;
  transition: transform .35s cubic-bezier(.2,.8,.2,1);
}
.cat:hover { transform: translateY(-4px); }
.cat-bg { position: absolute; inset: 0; transition: transform .6s ease; }
.cat:hover .cat-bg { transform: scale(1.06); }
.cat-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(0,0,0,.55) 100%);
}
.cat-label {
  position: absolute; left: 20px; bottom: 20px; right: 20px;
  color: white;
  display: flex; justify-content: space-between; align-items: end;
}
.cat-label h4 { margin: 0; font-family: 'Playfair Display', serif; font-size: 22px; font-weight: 600; }
.cat-label .count { font-size: 12px; opacity: .8; letter-spacing: .1em; text-transform: uppercase; }
.cat-arrow {
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255,255,255,.18); backdrop-filter: blur(8px);
  display: inline-flex; align-items: center; justify-content: center;
  border: 1px solid rgba(255,255,255,.3);
  transition: background .2s ease;
}
.cat:hover .cat-arrow { background: rgba(255,255,255,.4); }

/* category swatches */
.cat-1 { background: linear-gradient(135deg, #f6e1d3, #e1b899); }
.cat-2 { background: linear-gradient(135deg, #d4dfd5, #8aab93); }
.cat-3 { background: linear-gradient(135deg, #e6d9c2, #b59b73); }
.cat-4 { background: linear-gradient(135deg, #d5d2e2, #9f99b8); }

.cat-illu {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
}

/* ---------- Featured products ---------- */
.featured-tabs {
  display: flex; gap: 8px; margin-bottom: 28px; flex-wrap: wrap;
}
.tab {
  padding: 9px 18px; border-radius: 999px;
  font-size: 13px; font-weight: 500;
  border: 1px solid var(--line);
  transition: background .2s ease, color .2s ease, border-color .2s ease;
}
.tab:hover { background: rgba(0,0,0,.04); }
.tab.active { background: var(--ink); color: white; border-color: var(--ink); }

.products {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .25s ease, box-shadow .25s ease;
  position: relative;
}
.product:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.product-image {
  aspect-ratio: 1/1;
  position: relative; overflow: hidden;
  display: flex; align-items: center; justify-content: center;
}
.product-tag {
  position: absolute; top: 14px; left: 14px;
  background: var(--surface); color: var(--ink);
  padding: 5px 11px; border-radius: 999px;
  font-size: 11px; font-weight: 600; letter-spacing: .05em;
  text-transform: uppercase;
  z-index: 2;
}
.product-tag.sale { background: var(--brand); color: white; }
.product-tag.new { background: var(--ink); color: white; }

.wishlist-btn {
  position: absolute; top: 12px; right: 12px;
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(255,255,255,.9);
  display: flex; align-items: center; justify-content: center;
  z-index: 2;
  transition: background .2s ease, transform .2s ease;
}
.wishlist-btn:hover { background: white; transform: scale(1.08); }
.wishlist-btn svg { width: 16px; height: 16px; transition: fill .2s ease, stroke .2s ease; fill: none; stroke: var(--ink); stroke-width: 1.8; }
.wishlist-btn.active svg { fill: var(--brand); stroke: var(--brand); }

.quick-add {
  position: absolute; left: 14px; right: 14px; bottom: 14px;
  background: var(--ink); color: white;
  text-align: center; padding: 12px;
  border-radius: 10px;
  font-size: 13px; font-weight: 600;
  opacity: 0; transform: translateY(8px);
  transition: opacity .25s ease, transform .25s ease;
  z-index: 2;
}
.product:hover .quick-add { opacity: 1; transform: translateY(0); }

.product-info { padding: 18px 18px 22px; }
.product-cat { font-size: 11px; color: var(--muted); letter-spacing: .12em; text-transform: uppercase; margin-bottom: 4px; }
.product-name { font-size: 15px; font-weight: 500; margin: 0 0 10px; }
.product-meta { display: flex; justify-content: space-between; align-items: center; }
.price { display: flex; align-items: baseline; gap: 8px; }
.price .now { font-weight: 600; font-size: 16px; }
.price .was { color: var(--muted); text-decoration: line-through; font-size: 13px; }
.swatches { display: flex; gap: 5px; }
.swatch { width: 14px; height: 14px; border-radius: 50%; border: 1px solid rgba(0,0,0,.15); }

.product-illu {
  width: 70%; height: 70%;
  display: flex; align-items: center; justify-content: center;
}

/* product backgrounds */
.pbg-1 { background: linear-gradient(135deg, #f3ebe0, #e3d3b8); }
.pbg-2 { background: linear-gradient(135deg, #e6e2d6, #c8c0a8); }
.pbg-3 { background: linear-gradient(135deg, #e8d6cd, #c89c8a); }
.pbg-4 { background: linear-gradient(135deg, #d8e1dd, #9eb6a9); }
.pbg-5 { background: linear-gradient(135deg, #efe5dd, #d4b894); }
.pbg-6 { background: linear-gradient(135deg, #ddd8e6, #a89cc1); }
.pbg-7 { background: linear-gradient(135deg, #e8e0d2, #b9a578); }
.pbg-8 { background: linear-gradient(135deg, #f0d9d4, #c98a82); }

/* ---------- Deals banner ---------- */
.deals-section { background: linear-gradient(180deg, var(--bg) 0%, #f1ede4 100%); }
.deals-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 20px;
}
.deal {
  position: relative;
  border-radius: 20px;
  overflow: hidden;
  min-height: 280px;
  padding: 40px;
  display: flex; flex-direction: column; justify-content: space-between;
  color: white;
}
.deal-main {
  background: linear-gradient(135deg, #2b2b2b 0%, #4a4a4a 100%);
  min-height: 580px;
  grid-row: span 2;
}
.deal-side-1 { background: linear-gradient(135deg, #c9402f 0%, #9a2e22 100%); }
.deal-side-2 { background: linear-gradient(135deg, #b08a4f 0%, #8a6a36 100%); }

.deal-eyebrow {
  font-size: 11px; letter-spacing: .22em; text-transform: uppercase;
  font-weight: 600; opacity: .85;
}
.deal-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.6rem, 2.5vw, 2.4rem);
  margin: 12px 0;
  font-weight: 600; line-height: 1.05; letter-spacing: -0.01em;
}
.deal-main .deal-title { font-size: clamp(2.4rem, 4vw, 3.6rem); max-width: 480px; }
.deal-desc { opacity: .85; max-width: 380px; margin: 0 0 24px; }
.deal-cta {
  display: inline-flex; align-items: center; gap: 10px;
  font-size: 14px; font-weight: 600; padding: 12px 22px;
  background: rgba(255,255,255,.15); border-radius: 999px;
  border: 1px solid rgba(255,255,255,.25);
  align-self: flex-start;
  backdrop-filter: blur(8px);
  transition: background .2s ease;
}
.deal-cta:hover { background: rgba(255,255,255,.28); }

.deal-timer {
  display: flex; gap: 12px; margin-top: 24px;
}
.timer-block {
  background: rgba(255,255,255,.12);
  border: 1px solid rgba(255,255,255,.2);
  border-radius: 10px;
  padding: 14px 18px;
  text-align: center;
  min-width: 70px;
  backdrop-filter: blur(8px);
}
.timer-num { font-size: 26px; font-weight: 700; font-family: 'Playfair Display', serif; }
.timer-lbl { font-size: 10px; letter-spacing: .2em; text-transform: uppercase; opacity: .8; margin-top: 4px; }

.deal-decoration {
  position: absolute; right: -40px; bottom: -40px;
  width: 280px; height: 280px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255,255,255,.1) 0%, transparent 70%);
}
.deal-percent {
  position: absolute; top: 28px; right: 28px;
  font-family: 'Playfair Display', serif;
  font-size: 64px; font-weight: 700;
  opacity: .25;
}

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px;
}
.article {
  background: var(--surface);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .25s ease, box-shadow .25s ease;
}
.article:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.article-image {
  aspect-ratio: 4/3;
  position: relative; overflow: hidden;
  display: flex; align-items: center; justify-content: center;
}
.article-image::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,.2) 100%);
}
.article-meta {
  position: absolute; top: 16px; left: 16px;
  background: rgba(255,255,255,.9);
  padding: 5px 11px; border-radius: 999px;
  font-size: 11px; font-weight: 600; letter-spacing: .05em;
  text-transform: uppercase; color: var(--ink);
  z-index: 2;
}
.article-body { padding: 24px 24px 28px; }
.article-info { display: flex; gap: 12px; font-size: 12px; color: var(--muted); margin-bottom: 10px; letter-spacing: .05em; }
.article-info span { display: flex; align-items: center; gap: 6px; }
.article-info .dot { width: 3px; height: 3px; background: var(--muted); border-radius: 50%; }
.article-title {
  font-family: 'Playfair Display', serif;
  font-size: 22px; font-weight: 600; line-height: 1.25;
  margin: 0 0 12px; letter-spacing: -0.005em;
}
.article-excerpt { color: var(--muted); font-size: 14px; margin: 0 0 18px; }
.article-link {
  font-size: 13px; font-weight: 600;
  display: inline-flex; align-items: center; gap: 8px;
  border-bottom: 1px solid var(--ink);
  padding-bottom: 3px;
}
.article-link:hover { color: var(--brand); border-color: var(--brand); }

.ar-1 { background: linear-gradient(135deg, #e8d8c2, #b8956a); }
.ar-2 { background: linear-gradient(135deg, #d2dcd5, #7d9c87); }
.ar-3 { background: linear-gradient(135deg, #e2d2d8, #b88a98); }

/* ---------- Newsletter ---------- */
.newsletter {
  margin: 48px auto;
  max-width: var(--maxw);
  padding: 60px 56px;
  border-radius: 24px;
  background: linear-gradient(135deg, #1a1a1a 0%, #2e2e2e 100%);
  color: white;
  position: relative; overflow: hidden;
}
.newsletter::before, .newsletter::after {
  content: ""; position: absolute; border-radius: 50%;
  background: radial-gradient(circle, rgba(176,138,79,.3) 0%, transparent 70%);
}
.newsletter::before { width: 400px; height: 400px; top: -100px; right: -100px; }
.newsletter::after { width: 300px; height: 300px; bottom: -100px; left: -50px; background: radial-gradient(circle, rgba(201,64,47,.2) 0%, transparent 70%); }
.newsletter-inner {
  position: relative; z-index: 2;
  display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: center;
}
.newsletter-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.8rem, 3vw, 2.6rem); font-weight: 600;
  margin: 12px 0 16px; line-height: 1.1;
}
.newsletter-desc { opacity: .8; max-width: 420px; }
.newsletter-form { display: flex; gap: 12px; flex-wrap: wrap; }
.newsletter-input {
  flex: 1; min-width: 240px;
  padding: 16px 22px; border-radius: 999px;
  background: rgba(255,255,255,.1);
  border: 1px solid rgba(255,255,255,.15);
  color: white; font-size: 14px; font-family: inherit;
  outline: none;
  transition: background .2s ease, border-color .2s ease;
}
.newsletter-input::placeholder { color: rgba(255,255,255,.5); }
.newsletter-input:focus { background: rgba(255,255,255,.15); border-color: rgba(255,255,255,.4); }
.newsletter-submit {
  background: white; color: var(--ink);
  padding: 16px 28px; border-radius: 999px;
  font-weight: 600; font-size: 14px;
  transition: background .2s ease;
}
.newsletter-submit:hover { background: var(--gold); color: white; }

.perks {
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 24px; padding: 48px 0;
  border-top: 1px solid var(--line);
}
.perk { display: flex; gap: 14px; align-items: flex-start; }
.perk-icon {
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--surface); border: 1px solid var(--line);
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.perk-icon svg { width: 20px; height: 20px; stroke: var(--ink); fill: none; stroke-width: 1.6; }
.perk h5 { margin: 0 0 4px; font-size: 14px; font-weight: 600; }
.perk p { margin: 0; font-size: 13px; color: var(--muted); }

/* ---------- Footer ---------- */
.footer {
  background: #f1ede4;
  padding: 72px 0 32px;
  border-top: 1px solid var(--line);
}
.footer-grid {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 48px;
  margin-bottom: 48px;
}
.footer-brand .brand { text-align: left; font-size: 30px; }
.footer-tag { color: var(--muted); margin: 16px 0 24px; max-width: 280px; }
.footer-social { display: flex; gap: 10px; }
.footer-social a {
  width: 38px; height: 38px; border-radius: 50%;
  background: white; border: 1px solid var(--line);
  display: flex; align-items: center; justify-content: center;
  transition: background .2s ease, color .2s ease;
}
.footer-social a:hover { background: var(--ink); color: white; }
.footer-social svg { width: 16px; height: 16px; }

.footer-col h6 {
  font-size: 12px; letter-spacing: .15em; text-transform: uppercase;
  margin: 0 0 18px; font-weight: 600;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; }
.footer-col li { margin-bottom: 10px; }
.footer-col a { font-size: 14px; color: #444; }
.footer-col a:hover { color: var(--brand); }

.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  padding-top: 28px; border-top: 1px solid var(--line);
  font-size: 13px; color: var(--muted); flex-wrap: wrap; gap: 16px;
}
.payments { display: flex; gap: 8px; }
.pay-chip {
  padding: 4px 10px; background: white; border: 1px solid var(--line);
  border-radius: 6px; font-size: 11px; font-weight: 700; letter-spacing: .05em;
}

/* ---------- SVG illustrations ---------- */
.illu { width: 100%; height: 100%; }

/* ---------- Toast ---------- */
.toast {
  position: fixed; bottom: 28px; left: 50%; transform: translateX(-50%) translateY(120%);
  background: var(--ink); color: white;
  padding: 14px 22px; border-radius: 999px;
  font-size: 14px; font-weight: 500;
  box-shadow: var(--shadow-md);
  transition: transform .35s cubic-bezier(.2,.9,.3,1.2);
  z-index: 100;
  display: inline-flex; align-items: center; gap: 10px;
}
.toast.show { transform: translateX(-50%) translateY(0); }
.toast .check {
  width: 20px; height: 20px; border-radius: 50%;
  background: #4ade80; display: inline-flex; align-items: center; justify-content: center;
  color: var(--ink); font-weight: 700; font-size: 12px;
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .hero-card { grid-template-columns: 1fr; min-height: auto; }
  .hero-content { padding: 48px 32px; }
  .hero-visual { min-height: 380px; }
  .hero-stats { position: static; padding: 0 32px 32px; }
  .cats { grid-template-columns: repeat(2, 1fr); }
  .products { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-main { grid-row: auto; min-height: 380px; }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
  .perks { grid-template-columns: repeat(2, 1fr); }
  .newsletter-inner { grid-template-columns: 1fr; }
  .newsletter { padding: 48px 32px; margin: 32px 24px; }
}
@media (max-width: 640px) {
  .nav { display: none; }
  .header-inner { grid-template-columns: 1fr auto 1fr; }
  .topbar-links a:nth-child(1), .topbar-links a:nth-child(2) { display: none; }
  .products { grid-template-columns: repeat(2, 1fr); }
  .editorial-grid { grid-template-columns: 1fr; }
  .cats { grid-template-columns: 1fr 1fr; }
  .perks { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .hero-content { padding: 36px 24px; }
  .hero-title { font-size: 2.4rem; }
  section { padding: 56px 0; }
}
