function CountdownTimer() {
  const target = useMemo(() => Date.now() + 1000 * 60 * 60 * 47 + 1000 * 60 * 32, []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const diff = Math.max(0, target - now);
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff % 86400000) / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const block = (n, l) => e('div', { className: 'timer-block', key: l },
    e('div', { className: 'timer-num' }, String(n).padStart(2, '0')),
    e('div', { className: 'timer-lbl' }, l)
  );
  return e('div', { className: 'deal-timer' },
    block(d, 'Days'), block(h, 'Hrs'), block(m, 'Min'), block(s, 'Sec')
  );
}

