function Perks() {
  const perks = [
    { icon: 'truck', title: 'Free shipping', text: 'On all orders over $75' },
    { icon: 'refresh', title: 'Easy returns', text: '30-day no questions asked' },
    { icon: 'leaf', title: 'Clean & conscious', text: 'Sustainably sourced ingredients' },
    { icon: 'shield', title: 'Secure checkout', text: 'SSL encrypted payments' },
  ];
  return e('div', { className: 'container' },
