  );
}

function Footer() {
  const cols = [
    { title: 'Shop', items: ['New Arrivals', 'Best Sellers', 'Skincare', 'Fragrance', 'Home', 'Gift Cards'] },
    { title: 'Help', items: ['Shipping', 'Returns', 'Contact us', 'FAQ', 'Order tracking'] },
