/* ---------- App ---------- */

function App() {
  const [bag, setBag] = useState([]);
  const [wishlist, setWishlist] = useState([]);
  const [toast, setToast] = useState({ show: false, msg: '' });
  const toastTimer = useRef(null);

  const showToast = (msg) => {
    setToast({ show: true, msg });
    clearTimeout(toastTimer.current);
    toastTimer.current = setTimeout(() => setToast(t => ({ ...t, show: false })), 2400);
  };

  const handleAdd = (p) => {
    setBag(b => [...b, p.id]);
    showToast(`Added "${p.name}" to bag`);
  };
  const handleWish = (id) => {
    setWishlist(w => w.includes(id) ? w.filter(x => x !== id) : [...w, id]);
  };
  const handleSubscribe = (email) => showToast(`Welcome \u2014 ${email} subscribed.`);

  return e(Fragment, null,
    e(TopBar),
    e(Header, { bagCount: bag.length, wishCount: wishlist.length, onBagClick: () => showToast(`You have ${bag.length} item${bag.length === 1 ? '' : 's'} in your bag`) }),
    e(Hero, { onShop: () => document.getElementById('new').scrollIntoView({ behavior: 'smooth' }) }),
    e(Marquee),
    e(Categories),
    e(FeaturedProducts, { onAdd: handleAdd, onWish: handleWish, wishlist }),
    e(Deals),
    e(Editorial),
    e(Newsletter, { onSubscribe: handleSubscribe }),
    e(Perks),
    e(Footer),
    e(Toast, { msg: toast.msg, show: toast.show })
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(e(App));
